import assert from "node:assert/strict";
import fs from "node:fs";
import {stageFirstPartyMassBatch,mergeStagedFirstPartyMasses} from "../tools/directory/ingest-firstparty-mass-batch.mjs";
import {expandResearchProviderSnapshot,joinDirectoryRecords,publishableDirectoryRecords} from "../src/find/data-service.js";

const read=path=>JSON.parse(fs.readFileSync(path,"utf8"));
const manifest=read("data/directory/research/gb-firstparty-8-original-source-manifest-20261009.v1.json");
const corpus=read("data/directory/generated/v19/diocesan.v1.json");
assert.equal(manifest.schema,"AO_EDITOR_REVIEWED_FIRSTPARTY_MASS_BATCH_V1");
assert.equal(manifest.records.length,8);
assert.equal(corpus.records.length,73);
const prev={...corpus,records:corpus.records.filter(row=>!manifest.records.some(r=>r.u===row.u))};
assert.equal(prev.records.length,65);
const first=stageFirstPartyMassBatch(prev,manifest);
assert.equal(first.summary.accepted,8,JSON.stringify(first.holds));
assert.equal(first.summary.held,0);
const merged=mergeStagedFirstPartyMasses(prev,first);
assert.equal(merged.records.length,73);
const repeated=stageFirstPartyMassBatch(merged,manifest);
assert.equal(repeated.summary.accepted,0);
assert.equal(repeated.summary.held,8);
assert.equal(new Set(corpus.records.map(x=>x.u)).size,73);
const joined=publishableDirectoryRecords(joinDirectoryRecords(expandResearchProviderSnapshot(corpus)));
for(const evidence of manifest.records){
 const row=corpus.records.find(r=>r.u===evidence.u);
 assert.ok(row,evidence.u+" not in canonical source");
 assert.equal(row.cc,"GB");
 assert.equal(row.su,evidence.su);
 assert.equal(row.eu,evidence.eu);
 assert.equal(row.sr,evidence.sr);
 assert.equal(row.st,evidence.st);
 assert.equal(row.vv,"2026-10-09");
 assert.ok(evidence.editorial_liturgical_evidence.length>40);
 assert.ok(["CATHEDRAL_OFFICIAL","PARISH_OFFICIAL","SHRINE_OFFICIAL"].includes(row.st));
 const r=joined.find(x=>x.venue.upstream.upstream_id===evidence.u);
 assert.ok(r,"No joined Mass venue "+evidence.u);
 assert.ok(r.ministries.some(m=>m.community_id==="DIOCESAN"&&m.schedules.some(s=>s.service_type==="MASS")));
 assert.ok(r.sources.some(s=>s.url===row.su));
}
const byId=Object.fromEntries(manifest.records.map(r=>[r.u,r]));
assert.match(byId["DIO-GB-EASTANGLIA-NORWICH-CATHEDRAL"].sr,/FIRST_SUNDAY_15:00/);
assert.doesNotMatch(byId["DIO-GB-EASTANGLIA-NORWICH-CATHEDRAL"].sr,/WEEKLY_15:00/);
assert.match(byId["DIO-GB-WESTMINSTER-SPANISHPLACE-ST-JAMES"].sr,/SUNDAY_09:00_EXTRAORDINARY/);
assert.match(byId["DIO-GB-WESTMINSTER-SPANISHPLACE-ST-JAMES"].sr,/10:30_SUNG_LATIN_NOT_AUTOMATICALLY_1962/);
assert.match(byId["DIO-GB-WESTMINSTER-WARWICK-STREET-ASSUMPTION"].sr,/ORDINARIATE_SUNDAY_SERVICES_DISTINCT/);
assert.match(byId["DIO-GB-SOUTHWARK-RAMSGATE-ST-AUGUSTINE"].sr,/FRIDAY_ORDINARIATE_NOT_1962/);
assert.match(byId["DIO-GB-BRENTWOOD-CANNINGTOWN-CONVENT"].sr,/ROMANIAN_GREEK_CATHOLIC_12:00_SEPARATE/);
assert.match(byId["DIO-GB-HEXHAM-NEWCASTLE-GATESHEAD-ST-JOSEPH"].sr,/SUNDAY_12:00_LATIN_EXTRAORDINARY_FORM/);
assert.equal(joined.filter(x=>manifest.records.some(r=>r.u===x.venue.upstream.upstream_id)).length,8);
console.log("GB original-source batch: PASS — 8 publishable churches, first-party schedule citations, no duplicate run, liturgical-form boundaries");
